import heapq
from dataclasses import dataclass, field


@dataclass(order=True)
class Job:
    priority: int
    name: str = field(compare=False)
    deadline: float = field(compare=False, default=float("inf"))


class Scheduler:
    """A min-heap of jobs; ties broken by insertion order."""

    def __init__(self) -> None:
        self._heap: list[tuple[int, int, Job]] = []
        self._counter = 0
        self._cancelled: set[str] = set()

    def __len__(self) -> int:
        return len(self._heap) - len(self._cancelled)

    def push(self, job: Job) -> None:
        heapq.heappush(self._heap, (job.priority, self._counter, job))
        self._counter += 1

    def cancel(self, name: str) -> None:
        """Mark a job as cancelled; it is dropped lazily when it reaches the top."""
        self._cancelled.add(name)

    def _discard_cancelled(self) -> None:
        while self._heap and self._heap[0][2].name in self._cancelled:
            _, _, job = heapq.heappop(self._heap)
            self._cancelled.discard(job.name)

    def pop(self) -> Job:
        self._discard_cancelled()
        if not self._heap:
            raise IndexError("pop from an empty scheduler")
        return heapq.heappop(self._heap)[2]

    def peek(self) -> Job | None:
        self._discard_cancelled()
        return self._heap[0][2] if self._heap else None

    def drain_before(self, t: float) -> list[Job]:
        """Remove and return every job whose deadline is before t, in priority order."""
        due, keep = [], []
        while self._heap:
            prio, seq, job = heapq.heappop(self._heap)
            if job.name in self._cancelled:
                self._cancelled.discard(job.name)
                continue
            (due if job.deadline < t else keep).append((prio, seq, job))
        for item in keep:
            heapq.heappush(self._heap, item)
        return [job for _, _, job in due]


def run(scheduler: Scheduler, now: float, budget: int) -> list[str]:
    """Run at most `budget` jobs that are still on time and return their names in the order they ran."""
    done = []
    for job in scheduler.drain_before(now):
        print(f"late: {job.name} (deadline {job.deadline:.1f})")
    while budget > 0 and len(scheduler) > 0:
        job = scheduler.pop()
        done.append(job.name)
        budget -= 1
    return done


if __name__ == "__main__":
    s = Scheduler()
    for i, (prio, name, deadline) in enumerate([(2, "backup", 9.0), (1, "email", 3.5), (3, "report", 1.0),
                                                 (1, "deploy", 7.25), (2, "cleanup", 12.0)]):
        s.push(Job(prio, name, deadline))
    s.cancel("cleanup")
    print(run(s, now=2.0, budget=3))
